using System;
using System.Globalization;

foreach (long n in new long[] { 0, 7, 999, 1000, -456789, 3141592, 9876543210 })
{
    bool negative = n < 0;
    long magnitude = Math.Abs(n);
    Console.WriteLine((negative ? "-" : "") + magnitude.ToString("N0", CultureInfo.InvariantCulture));
}
